fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut out = Vec::with_capacity(a.len());
    let sep = sep; // take ownership of the separator
    let max = maxsplit as usize;

    for s in a {
        // rsplitn(max+1, ...) will perform at most `max` splits, yielding up to max+1 parts
        let mut parts: Vec<String> =
            s.rsplitn(max + 1, sep.as_str())
             .map(|p| p.to_string())
             .collect();
        // rsplitn yields substrings starting from the rightmost split,
        // so reverse to restore left‐to‐right order of the parts.
        parts.reverse();
        out.push(parts);
    }

    out
}